#include <memory>
#include <iostream>

struct Resource { ~Resource() { std::cout << "Resource released.\n"; } };

void vulnerable_function() {
    Resource* r = new Resource(); // Acquire
    throw 1; // Exception thrown before explicit delete
    delete r; // Free (Never reached, causes leak)
}

void safe_function() {
    // Resource bound to auto_ptr (RAII)
    std::auto_ptr<Resource> r(new Resource());
    throw 1; // Destructor called during stack unwind
    // No explicit delete needed
}
